from html.parser import HTMLParser
from urllib.parse import unquote
class P(HTMLParser):
    def __init__(self): super().__init__(); self.in_h=False; self.in_p=False; self.href=''; self.buf=''; self.results=[]
    def handle_starttag(self,t,a):
        d=dict(a)
        if t=='h2': self.in_h=True; self.buf=''
        if t=='a' and self.in_h: self.href=d.get('href','')
        if t=='p': self.in_p=True; self.buf=''
    def handle_data(self,d):
        if self.in_h or self.in_p: self.buf+=d
    def handle_endtag(self,t):
        if t=='h2' and self.in_h:
            self.results.append((self.buf.strip(),self.href)); self.in_h=False
        if t=='p' and self.in_p: self.in_p=False
p=P(); p.feed(open(\""'$TMPDIR/search_bhratiya_bing2.html").read())
for title, href in p.results[:15]: print(title,'"'\\t',unquote(href))
