from html.parser import HTMLParser
import sys,re
class P(HTMLParser):
 def __init__(self): super().__init__(); self.stack=[]; self.text=[]; self.links=[]; self.cur=None
 def handle_starttag(self,t,a):
  d=dict(a); self.stack.append(t)
  if t=='a': self.cur=[d.get('href',''),[]]
 def handle_data(self,d):
  if self.cur: self.cur[1].append(d)
  self.text.append(d)
 def handle_endtag(self,t):
  if t=='a' and self.cur:
   self.links.append((self.cur[0],''.join(self.cur[1]).strip())); self.cur=None
  if self.stack: self.stack.pop()
p=P(); p.feed(open(sys.argv[1],encoding='utf8',errors='ignore').read())
print('TEXT\\n',re.sub(r'\\s+',' ',' '.join(p.text)).strip())
print('\\nLINKS')
for h,t in p.links: print(t,'\\t',h)
PY"

